(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-286":{scenario:{company:"Nam Phong Enterprise Solutions",supervisor:{name:"Đặng Hải Yến",role:{vi:"Giám đốc Khách hàng Doanh nghiệp",en:"Head of Enterprise Sales"}},ref_code:"QO-5560",title:{vi:"Đúng gói giải pháp. Đúng giá trị hợp đồng.",en:"Right plan. Right contract value."},brief:{vi:"Khách hàng là một nhà máy may cần phần mềm quản trị nhân sự, tiền lương cho 180 người dùng, bắt buộc có đăng nhập một lần (SSO). Các gói: STD-50 (tối đa 50 người dùng), BIZ-150 (tối đa 150, không có SSO), ENT-500 (tối đa 500, có SSO) giá niêm yết 95000 đ/người dùng/tháng. Hợp đồng 12 tháng. Đối chiếu đề xuất nháp QO-5560 với hồ sơ đã duyệt, sửa gói đề xuất và giá trị hợp đồng (VND, số liệu mô phỏng), rồi lập báo cáo.",en:"The client, a garment factory, needs HR and payroll software for 180 users with mandatory single sign-on (SSO). Plans: STD-50 (up to 50 users), BIZ-150 (up to 150, no SSO), ENT-500 (up to 500, with SSO) at a list price of 95000 VND per user per month. The contract runs 12 months. Compare draft proposal QO-5560 with the approved file, correct the proposed plan and the contract value (VND, simulated figures), then write a report."},reference_title:{vi:"Hồ sơ yêu cầu khách & chính sách giá đã duyệt · QO-5560",en:"Approved client requirements & pricing policy · QO-5560"},fields:[{id:"PLAN_CODE",label:{vi:"Gói giải pháp đề xuất",en:"Proposed plan"},initial:"BIZ-150",expected:"ENT-500",choices:["STD-50","BIZ-150","ENT-500"],reference:"Bảng yêu cầu khách hàng đã xác nhận",hint:{vi:"Gói phải đáp ứng đủ số người dùng và yêu cầu bắt buộc SSO, không chọn gói rẻ hơn rồi hứa nâng cấp sau.",en:"The plan must cover all users and the mandatory SSO; do not pick a cheaper plan and promise an upgrade later."}},{id:"TCV_VND",label:{vi:"Giá trị hợp đồng trước thuế (VND)",en:"Contract value before tax (VND)"},initial:"174420000",expected:"175446000",reference:"Chính sách chiết khấu đã duyệt",ref_value:{vi:"Chiết khấu 10% khi trên 100 người dùng và 5% khi trả trước cả năm, áp dụng nối tiếp",en:"10% discount above 100 users and 5% for annual prepayment, applied sequentially"},hint:{vi:"Hai chiết khấu áp dụng nối tiếp: nhân lần lượt từng hệ số, không cộng gộp phần trăm.",en:"The two discounts apply in sequence: multiply by each factor in turn, never add the percentages."}}],sop32:{vi:"Giá trị hợp đồng = số người dùng x giá niêm yết x số tháng x (1 - chiết khấu thứ nhất) x (1 - chiết khấu thứ hai); không cộng gộp các tỷ lệ chiết khấu; khách đã xác nhận trả trước cả năm.",en:"Contract value = users x list price x months x (1 - first discount) x (1 - second discount); never add discount rates together; the client has confirmed annual prepayment."},context:{label:"CRM / QO-5560",metrics:[{label:{vi:"Số người dùng",en:"Users"},value:"180"},{label:{vi:"Giá niêm yết (đ/người dùng/tháng)",en:"List price (VND/user/month)"},value:"95,000"},{label:{vi:"Thời hạn (tháng)",en:"Term (months)"},value:"12"}]},crisis:{vi:"Giám đốc vùng nhắn: “Cứ ghi trong đề xuất là đã có tích hợp máy chấm công, hứa khách tháng 1 dùng được để chốt trong quý. Sản phẩm chưa có lộ trình thì tính sau.”",en:"The regional director messages you: “Write in the proposal that time-clock integration already exists and promise it for January to close this quarter. We'll deal with the missing roadmap later.”"},options:{safe:{vi:"Không ghi tính năng chưa có; nêu đúng hiện trạng, đề xuất tích hợp qua API hoặc đối tác có thử nghiệm, báo Giám đốc Khách hàng Doanh nghiệp và xin cam kết chính thức từ bộ phận sản phẩm.",en:"Do not claim a missing feature; state the real status, offer API or partner integration with a pilot, inform the Head of Enterprise Sales and seek a formal product commitment."},shortcut:{vi:"Ghi tính năng tích hợp là ‘đã có’ và hứa tháng 1 để chốt hợp đồng trong quý.",en:"Mark the integration as ‘available’ and promise January to close the deal this quarter."},wait:{vi:"Không gửi đề xuất, chờ khách tự hỏi lại về tích hợp.",en:"Hold the proposal and wait for the client to ask about integration again."}},questions:{vi:["Vì sao đề xuất gói ENT-500 thay vì BIZ-150? Yêu cầu nào của khách chứng minh?","Trình bày cách tính giá trị hợp đồng với hai chiết khấu và cách xử lý áp lực hứa tính năng chưa có trong đề xuất."],en:["Why propose ENT-500 instead of BIZ-150? Which client requirement proves it?","Explain how you calculated the contract value with two discounts and how you handle pressure to promise a feature that does not exist."]},hints:{vi:["Đặt đề xuất nháp cạnh bảng yêu cầu khách đã xác nhận, đánh dấu yêu cầu mà gói hiện tại không đáp ứng.","Áp từng chiết khấu nối tiếp lên giá niêm yết cả năm theo SOP mục 3.2.","Đọc lại SOP mục 4.2: đề xuất phải mô tả đúng năng lực sản phẩm; cam kết lộ trình cần phê duyệt chính thức."],en:["Place the draft proposal next to the confirmed requirements and flag what the current plan cannot meet.","Apply each discount in sequence to the annual list price per SOP 3.2.","Re-read SOP 4.2: proposals must describe real product capability; roadmap commitments need formal approval."]}},learning:{summary:{vi:"Chuyên viên kinh doanh giải pháp doanh nghiệp (Account Executive) tìm kiếm và chốt hợp đồng với khách hàng tổ chức: khai thác bài toán kinh doanh, xác định người ra quyết định, thiết kế giải pháp cùng đội kỹ thuật, lập đề xuất, đàm phán giá và điều khoản. Công việc đòi hỏi bán hàng tư vấn, quản lý chu kỳ bán dài với nhiều bên liên quan, dự báo doanh số chính xác và cam kết trung thực với khách.",en:"A B2B account executive finds and closes deals with organizational clients: uncovering business problems, mapping decision makers, shaping solutions with presales engineers, writing proposals and negotiating price and terms. The role demands consultative selling, managing long multi-stakeholder cycles, accurate forecasting and honest commitments to clients."},responsibilities:{vi:["Tìm kiếm, sàng lọc khách hàng doanh nghiệp phù hợp chân dung khách hàng mục tiêu.","Khai thác nhu cầu, xác định tiêu chí quyết định, ngân sách và sơ đồ người ra quyết định.","Phối hợp kỹ sư giải pháp demo, thử nghiệm (POC) và lập đề xuất giá trị, báo giá.","Đàm phán giá, chiết khấu trong thẩm quyền, điều khoản hợp đồng, SLA và chốt hợp đồng.","Quản lý pipeline trên CRM, dự báo doanh số và bàn giao khách cho đội triển khai, chăm sóc."],en:["Prospect and qualify organizations that fit the ideal customer profile.","Discover needs, decision criteria, budget and the map of decision makers.","Run demos and proofs of concept (POC) with solution engineers and write value proposals and quotes.","Negotiate price, discounts within authority, contract terms and SLAs, and close deals.","Manage the CRM pipeline, forecast revenue and hand clients over to delivery and success teams."]},competencies:[{name:{vi:"Bán hàng tư vấn",en:"Consultative selling"},desc:{vi:"Đặt câu hỏi khai thác bài toán, lượng hóa tác động và gắn giải pháp với kết quả kinh doanh.",en:"Ask discovery questions, quantify impact and tie the solution to business outcomes."}},{name:{vi:"Đánh giá cơ hội",en:"Deal qualification"},desc:{vi:"Áp dụng khung MEDDICC, BANT để xác định cơ hội thật và rủi ro.",en:"Apply MEDDICC and BANT to separate real opportunities from risky ones."}},{name:{vi:"Thiết kế đề xuất & định giá",en:"Proposal & pricing"},desc:{vi:"Chọn đúng gói, tính chiết khấu đúng chính sách và minh bạch giá trị hợp đồng.",en:"Choose the right plan, apply discounts per policy and keep contract value transparent."}},{name:{vi:"Đàm phán nhiều bên",en:"Multi-stakeholder negotiation"},desc:{vi:"Cân bằng lợi ích của mua hàng, CNTT, tài chính và ban giám đốc phía khách.",en:"Balance the interests of the client's procurement, IT, finance and leadership."}},{name:{vi:"Liêm chính bán hàng",en:"Sales integrity"},desc:{vi:"Không hứa tính năng chưa có, không chiết khấu ngầm; mọi cam kết phải có phê duyệt.",en:"Never promise missing features or hidden discounts; every commitment needs approval."}}],knowledge:{vi:["Các phương pháp bán hàng B2B: SPIN Selling, Challenger Sale, MEDDICC và quản lý chu kỳ bán dài.","Chỉ số kinh doanh phần mềm thuê bao: ARR, ACV, TCV, tỷ lệ rời bỏ và tỷ lệ giữ chân doanh thu ròng.","Luật Thương mại 2005 (số 36/2005/QH11) và Bộ luật Dân sự 2015 (số 91/2015/QH13) về hợp đồng và trách nhiệm do vi phạm.","Luật Cạnh tranh 2018 (số 23/2018/QH14) về hành vi cạnh tranh không lành mạnh.","Quy định hiện hành về bảo vệ dữ liệu cá nhân khi giải pháp xử lý dữ liệu nhân sự của khách.","ISO 37001 về hệ thống quản lý chống hối lộ và chính sách quà tặng, chiêu đãi."],en:["B2B selling methods: SPIN Selling, the Challenger Sale, MEDDICC and long-cycle management.","Subscription software metrics: ARR, ACV, TCV, churn and net revenue retention.","Commercial Law 2005 (No. 36/2005/QH11) and Civil Code 2015 (No. 91/2015/QH13) on contracts and liability for breach.","Competition Law 2018 (No. 23/2018/QH14) on unfair competition practices.","Current personal data protection rules when the solution processes the client's HR data.","ISO 37001 anti-bribery management systems and gift and hospitality policies."]},tools:["Hệ thống CRM","Công cụ cấu hình báo giá (CPQ)","Nền tảng ký hợp đồng điện tử","Công cụ họp trực tuyến và demo","Bản đồ người ra quyết định (stakeholder map)"],kpis:{vi:["Doanh số ký mới so với chỉ tiêu (quota attainment).","Giá trị pipeline đủ điều kiện và độ phủ pipeline.","Tỷ lệ chốt và độ dài chu kỳ bán hàng.","Độ chính xác dự báo doanh số theo quý."],en:["New bookings against quota (quota attainment).","Qualified pipeline value and pipeline coverage.","Win rate and sales cycle length.","Quarterly forecast accuracy."]},day:[{time:"08:30",vi:"Rà soát pipeline, cập nhật bước tiếp theo cho các cơ hội sắp chốt trong quý.",en:"Review the pipeline and set next steps for deals closing this quarter."},{time:"10:00",vi:"Họp khám phá nhu cầu với khách mới cùng kỹ sư giải pháp.",en:"Hold a discovery meeting with a new prospect alongside a solution engineer."},{time:"13:30",vi:"Lập đề xuất, cấu hình báo giá trên CPQ và kiểm tra chiết khấu trong thẩm quyền.",en:"Write a proposal, configure the quote in CPQ and check discounts within authority."},{time:"15:30",vi:"Đàm phán điều khoản với bộ phận mua hàng, pháp chế của khách.",en:"Negotiate terms with the client's procurement and legal teams."},{time:"17:00",vi:"Cập nhật CRM, dự báo doanh số và báo cáo rủi ro cơ hội cho trưởng nhóm.",en:"Update the CRM and forecast and report deal risks to the sales lead."}],mistakes:{vi:["Chọn gói rẻ hơn không đáp ứng yêu cầu bắt buộc để thắng giá, gây xung đột khi triển khai.","Cộng gộp các tỷ lệ chiết khấu thay vì áp dụng nối tiếp, làm sai giá trị hợp đồng.","Hứa tính năng chưa có hoặc ghi ‘đã có’ trong đề xuất để chốt quý, gây tranh chấp và mất uy tín."],en:["Proposing a cheaper plan that misses mandatory requirements to win on price, causing conflict at rollout.","Adding discount rates together instead of applying them in sequence, misstating contract value.","Promising unbuilt features or marking them ‘available’ to close the quarter, leading to disputes and lost trust."]},career:[{vi:"Chuyên viên phát triển kinh doanh (SDR)",en:"Sales development representative"},{vi:"Chuyên viên kinh doanh giải pháp doanh nghiệp",en:"B2B account executive"},{vi:"Chuyên viên kinh doanh khách hàng chiến lược",en:"Strategic account executive"},{vi:"Giám đốc kinh doanh khối doanh nghiệp",en:"Head of enterprise sales"}],glossary:[{term:"Pipeline",vi:"Tập hợp cơ hội bán hàng theo từng giai đoạn, dùng để dự báo doanh số.",en:"The set of sales opportunities by stage, used to forecast revenue."},{term:"MEDDICC",vi:"Khung đánh giá cơ hội: chỉ số, người duyệt chi, tiêu chí và quy trình quyết định, nỗi đau, người ủng hộ, đối thủ.",en:"Qualification framework: metrics, economic buyer, decision criteria and process, pain, champion, competition."},{term:"TCV",vi:"Tổng giá trị hợp đồng trong toàn bộ thời hạn cam kết.",en:"Total contract value over the full committed term."},{term:"POC",vi:"Thử nghiệm chứng minh khái niệm trên dữ liệu, quy trình thật của khách trước khi ký.",en:"Proof of concept run on the client's real data and processes before signing."},{term:"Champion",vi:"Người ủng hộ bên trong tổ chức khách hàng, chủ động thúc đẩy giải pháp.",en:"An internal supporter at the client who actively pushes the solution."}],quiz:[{q:{vi:"Giá niêm yết 100 triệu đ, chiết khấu 10% rồi thêm 5% áp dụng nối tiếp. Giá sau chiết khấu là bao nhiêu?",en:"The list price is 100 million VND with 10% then 5% applied in sequence. What is the net price?"},options:{vi:["85 triệu đ","86 triệu đ","85,5 triệu đ","90 triệu đ"],en:["85 million VND","86 million VND","85.5 million VND","90 million VND"]},answer:2,explain:{vi:"100 x 0,9 x 0,95 = 85,5 triệu đ; cộng gộp 15% cho ra 85 triệu đ là sai.",en:"100 x 0.9 x 0.95 = 85.5 million VND; adding to 15% and getting 85 million is wrong."}},{q:{vi:"Trong MEDDICC, ‘Economic Buyer’ là ai?",en:"In MEDDICC, who is the ‘Economic Buyer’?"},options:{vi:["Người có quyền quyết định ngân sách cuối cùng","Người dùng cuối","Nhân viên mua hàng soạn hợp đồng","Đối thủ cạnh tranh"],en:["The person with final budget authority","The end user","The buyer drafting the contract","A competitor"]},answer:0,explain:{vi:"Economic Buyer là người có quyền phê duyệt chi tiêu cuối cùng, cần được tiếp cận sớm.",en:"The Economic Buyer holds final spending authority and should be engaged early."}},{q:{vi:"Cấp trên bảo ghi tính năng chưa phát triển là ‘đã có’ để chốt quý. Bạn làm gì?",en:"Your manager tells you to mark an unbuilt feature as ‘available’ to close the quarter. What do you do?"},options:{vi:["Ghi theo vì sau này sẽ có","Hứa miệng, không ghi văn bản","Bỏ qua yêu cầu của khách","Mô tả đúng hiện trạng, đề xuất phương án thay thế và xin cam kết lộ trình chính thức"],en:["Write it since it will come later","Promise verbally, put nothing in writing","Ignore the client's need","State the real status, offer an alternative and seek a formal roadmap commitment"]},answer:3,explain:{vi:"Mô tả sai năng lực sản phẩm là gian dối thương mại, gây tranh chấp hợp đồng và mất uy tín lâu dài.",en:"Misstating product capability is deceptive, triggers contract disputes and destroys long-term trust."}},{q:{vi:"Khách cần 180 người dùng và bắt buộc SSO; gói BIZ-150 rẻ hơn nhưng tối đa 150 người, không có SSO. Nên làm gì?",en:"A client needs 180 users and mandatory SSO; BIZ-150 is cheaper but caps at 150 users with no SSO. What should you do?"},options:{vi:["Đề xuất BIZ-150 rồi nâng cấp sau","Đề xuất gói đáp ứng đủ yêu cầu và giải thích giá trị","Chia khách thành hai hợp đồng","Bỏ yêu cầu SSO khỏi biên bản"],en:["Propose BIZ-150 and upgrade later","Propose the plan that meets every requirement and explain its value","Split the client into two contracts","Remove SSO from the minutes"]},answer:1,explain:{vi:"Đề xuất phải đáp ứng yêu cầu bắt buộc đã xác nhận; bán thiếu phạm vi sẽ thất bại khi triển khai.",en:"A proposal must meet confirmed mandatory requirements; underscoping fails at rollout."}}],tools_en:["CRM system","Configure-price-quote tool (CPQ)","E-signature platform","Online meeting and demo tools","Decision-maker stakeholder map"]}}})})(window.KKR);
